\phantomsection For any $M\in\mathrm{GL}_d(\mathbb R)$, writing $ \mathscr{A}_M=\{\bm{A}^M_{\mathtt{PDO}}[\bm{\psi}]; \: \bm{\psi}\in\mathbf{N}^d_b(\mathbb R)\}$, we have

			\begin{align*}
				\mathrm{WS}_{\mathscr{A}_M}(\bm{A}_\mathtt{PDO}[\bm\psi_0])=\mathscr{A}_M
			\end{align*}
where $\bm{\psi}_0(\bm{\xi})=(\xi^2_1,\ldots,\xi^2_d)$. More specifically, for any $\bm{\psi}\in\mathbf{N}^d_b(\mathbb R)$ and $M\in\mathrm{GL}_d(\mathbb{R})$, we have
\begin{align} \phantomsection
	\bm{A}^M_\mathtt{PDO}[\bm\psi]\bm{\Lambda}_{\bm\psi,M}=\bm{\Lambda}_{\bm\psi,M}\bm{A}_\mathtt{PDO}[\bm\psi_0] \ \text{ on } \ \bm{\mathcal{D}}(\mathbb R^d)
\end{align}
where $\bm{\Lambda}_{\bm \psi,M}:\mathbf{D}(\bm{\Lambda}_{\bm \psi,M}) \subset \mathbf{L}^{2}(\mathbb R^d,{\bf e})\to \mathbf{L}^{2}(\mathbb R^d,{\bf e}_M)$ is such that $\bm{\Lambda}_{\bm\psi,M}{\bf f}(\bm x)=\bm{\Lambda_\psi}{\bf f}(M\bm x)$, and $\bm{\Lambda}_{\bm \psi}$ is a shifted Fourier multiplier operator associated to
\begin{align*}
	\mathbf{m}^{\mathbf{e}}_{\bm{\Lambda}_{\bm\psi}}(\bm{\xi})=\prod_{k=1}^d \frac{W_{\phi_{+,k}}(\frac{1}{2}-\mathrm{i}\xi_k)}{W_{\phi_{-,k}}(\frac{1}{2}+\mathrm{i}\xi_k)}\frac{\Gamma(\frac{1}{2}+\mathrm{i}\xi_k)}{\Gamma(\frac{1}{2}-\mathrm{i}\xi_k)}.
\end{align*}
Moreover, for any $\bm{\psi}\in\mathbf{N}^d_+(\mathbb R)$, $\bm{\Lambda}_{\bm\psi,M}\in\mathscr{B}(\mathbf{L}^{2}(\mathbb{R}^d,{\bf e}),\mathbf{L}^{2}(\mathbb{R}^d,{\bf e}_M))$.

\phantomsection Let $\bm{P}^M[\bm{\psi}] \in \mathscr{P}$ for some $M\in\mathrm{GL}_d(\mathbb R)$. 



\begin{enumerate}
\item\phantomsection For all $t\geqslant 0$,
\begin{align*}
e^{t\mathbb{R}_-}\subseteq\sigma(\bm{P}^{M}_t[\bm{\psi}]).
\end{align*}
More precisely, if $\mathbf{m}^{\mathbf{e}}_{\bm{\psi}}$ is bounded then $e^{t\mathbb{R}_-}\subseteq\sigma_{ap}(\bm{P}^{M}_t[\bm{\psi}])$, where $\mathbf{m}^{\mathbf e}_{{\bm{\psi}}}$ is defined in (2.10). If $1/\mathbf{m}^{\mathbf{e}}_{\bm\psi}$ is bounded, then $e^{t\mathbb{R}_-}\subseteq\sigma_{ap}(\widehat{\bm{P}}^M_t[\bm{\psi}])$. \vspace{.2cm}
\item\phantomsection If $\mathbf{m}^{\mathbf{e}}_{\bm{\psi}}\in\mathbf{L}^{2}(\mathbb{R}^d)$ then \begin{equation*}
    e^{t\mathbb{R}_-}\subseteq\sigma_p(\bm{P}^M_t[\bm{\psi}])  \mbox{  and } \sigma_r(\bm{P}^M_t[\bm{\psi}])=\emptyset
     \end{equation*}
     with, for any $\bm{q}\in\mathbb{R}_+^d$, 
 \begin{equation*}
     \bm{P}^M_t[\bm{\psi}]  \uptau_{\ln \bm{q}}\mathbf{J}^M_{\bm{\psi}}(\bm{x})= \mathbf{e}(-t\bm{q}) \: \uptau_{\ln \bm{q}}\mathbf{J}^M_{\bm{\psi}}(\bm{x})
     \end{equation*}
     where $\uptau_{\bm{q}}\mathbf{f}(\bm{x})=\mathbf{f}(\bm{x}+\bm{q})$,  $\mathbf{J}^M_{\bm{\psi}}(\bm{x})= \mathbf{J}_{\bm{\psi}}(M^{-1}{\bm{x}})$,   and \[\mathbf{J}_{\bm{\psi}}(\bm{x})=\frac{\mathbf{e}(-\bm{x}/2)}{(2\pi)^{d/2}}\int_{\mathbb{R}^d}e^{{\rm{i}}\langle\bm{x},\bm{\xi}\rangle}\mathbf{m}^{\mathbf{e}}_{\bm \psi}(\bm \xi) d\bm{\xi} \]
      where the integral is understood in the ${\mathbf{L}}^2$-sense.
    \item \phantomsectionIf $1/\mathbf{m}^{\mathbf e}_{\bm\psi}\in\mathbf{L}^{2}(\mathbb{R}^d)$ then
         \begin{equation*}
    e^{t\mathbb{R}_-}\subseteq\sigma_r(\bm{P}^M_t[\bm{\psi}]) \mbox{ and } \sigma_p(\bm{P}^M_t[\bm{\psi}])=\emptyset
     \end{equation*}
     with,  for any $\bm{q}\in\mathbb{R}_+^d$, $t>0$ and $\mathbf{f}\in\mathbf{L}^{2}(\mathbb{R}^d,{\mathbf{e}}_M)$,
     \begin{equation*}
     \left\langle \bm{P}^M_t[\bm{\psi}] \mathbf{f},\uptau_{\ln \bm{q}}\mathbf{J}^M_{\overline{\bm{\psi}}}\right\rangle_{\mathbf{L}^{2}(\mathbb{R}^d,{\mathbf{e}}_M)}   = \mathbf{e}(-t\bm{q}) \left\langle \mathbf{f},\uptau_{\ln \bm{q}}\mathbf{J}^M_{\overline{\bm{\psi}}}\right\rangle_{\mathbf{L}^{2}(\mathbb{R}^d,{\mathbf{e}}_M)}.
     \end{equation*}
\item \phantomsection If $\mathbf{m}^{\mathbf e}_{\bm\psi}$ is both bounded from above and below then \begin{equation} \phantomsection
    \sigma(\bm{P}^M_t[\bm{\psi}])=\sigma_c(\bm{P}^M_t[\bm{\psi}])=e^{t\mathbb{R}_-}.
     \end{equation}
     In particular, when $\bm{P}^M_t[\bm{\psi}]$ is self-adjoint, i.e.~$\bm{\psi}=\overline{\bm{\psi}}$, then (2.11) holds. 
\end{enumerate}

\phantomsection
Let $M\in\mathrm{GL}_d(\mathbb R)$.
\begin{enumerate}
\item\phantomsection We have \[ \mathscr{P}_M \subset \mathcal{C}^+_0(\mathbf{L}^{2}(\mathbb{R}^d,{\mathbf{e}}_M)).\] More specifically, $\bm{P}^M[\bm{\psi}]$,  when restricted to $\mathbf{C}_0(\mathbb{R}^d) \cap \mathbf{L}^{2}(\mathbb{R}^d,{\mathbf{e}}_M)$, extends to the semigroup of the Feller process on $\mathbb{R}^d$ defined, for any $t\geqslant0$, as $\bm{Y}_t = M \bm{X}_t,$ where $\bm{X}_t=(\ln X^{(1)}_t, \ldots,\ln X^{(d)}_t)$, the stochastic processes $(X^{(k)}_t)_{t\geqslant0}, k=1,\ldots,d,$ are mutually independent  and each of them is a positive self-similar  Feller process on $(0,\infty)$, see Section 3.3 for more details on these processes.
	\item\phantomsection If $\bm{\psi}$ satisfies the conditions (2.16) and (2.17), then $\bm{\mathcal{E}}^M_{\bm \psi}:=\bm{H}^M_{\bm\psi}(\bm{\mathcal{E}})$ is a core for $\bm{A}_{\mathtt 2}[\bm \psi]$, and its restriction on $\bm{\mathcal{E}}^M_{\bm \psi}$  coincides with $\bm{A}^M[\bm\psi]$ defined in (2.15).
\end{enumerate}
